values (public.investment_system_wallet_id('59000000-0000-4000-8000-000000000001'),'59000000-0000-4000-8000-000000000001','Investment','investment','chart.line.uptrend.xyaxis','#9A67FF','VND',0,'investmentProfit','59000000-0000-4000-8000-000000000103');
insert into public.ledger_transactions(id,user_id,primary_kind_raw_value,transfer_subtype_raw_value,entry_status_raw_value,title,amount_minor,destination_amount_minor,occurred_at,source_wallet_id,destination_wallet_id,source_currency_code,destination_currency_code,reporting_currency_code,reporting_amount_minor,created_by_user_id,last_modified_by_user_id,settlement_role_raw_value)
values ('59000000-0000-4000-8000-000000000203','59000000-0000-4000-8000-000000000001','transfer','internalTransfer','posted','Reconciliation',30,30,'2026-10-27T00:00:00Z','59000000-0000-4000-8000-000000000101','59000000-0000-4000-8000-000000000103','VND','VND','VND',30,'59000000-0000-4000-8000-000000000001','59000000-0000-4000-8000-000000000001','investmentCashReconciliation');
create function pg_temp.reconciliation(p_id uuid,p_wallet uuid,p_amount bigint,p_event uuid default '59000000-0000-4000-8000-000000000601') returns jsonb language sql as $$
select pg_temp.posting(p_id,p_amount)||jsonb_build_object('event_id',p_event,'wallet_id',p_wallet,'ledger_transaction_id','59000000-0000-4000-8000-000000000203','role_raw_value','cashReconciliation')
$$;
select has_function('public','mutate_investment_cash_postings',array['jsonb','jsonb','boolean'],'compared batch overload is available alongside the legacy signature');
select lives_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301'),pg_temp.posting('59000000-0000-4000-8000-000000000303',40)),jsonb_build_object('59000000-0000-4000-8000-000000000301',0,'59000000-0000-4000-8000-000000000303',0),false)$$,'two compared zero-base rows create atomically');
select is((select count(*) from public.investment_wallet_postings where user_id='59000000-0000-4000-8000-000000000001'),2::bigint,'both requested owned rows were created');
select is((select array_agg(sync_version order by id)::text from public.investment_wallet_postings where user_id='59000000-0000-4000-8000-000000000001'),'{1,1}','each newly created row advances exactly once');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301'),pg_temp.posting('59000000-0000-4000-8000-000000000304')),jsonb_build_object('59000000-0000-4000-8000-000000000301',0,'59000000-0000-4000-8000-000000000304',0),false)$$,'P0001','version_conflict','a stale row rejects the entire compared batch');
select is((select count(*) from public.investment_wallet_postings where id='59000000-0000-4000-8000-000000000304'),0::bigint,'stale batch leaves no later inserted row');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')),'{}'::jsonb,false)$$,'P0001','investment_cash_invalid_expected_versions','missing key cannot grant batch comparison authority');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')),'{"59000000-0000-4000-8000-000000000301":1,"59000000-0000-4000-8000-000000000399":0}'::jsonb,false)$$,'P0001','investment_cash_invalid_expected_versions','extra key cannot grant batch comparison authority');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')),'{"59000000-0000-4000-8000-000000000301":"1"}'::jsonb,false)$$,'P0001','investment_cash_invalid_expected_versions','numeric string cannot grant batch comparison authority');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')),'{"59000000-0000-4000-8000-000000000301":1.5}'::jsonb,false)$$,'P0001','investment_cash_invalid_expected_versions','fraction cannot grant batch comparison authority');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')),'{"59000000-0000-4000-8000-000000000301":-1}'::jsonb,false)$$,'P0001','investment_cash_invalid_expected_versions','negative cannot grant batch comparison authority');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')),'{"59000000-0000-4000-8000-000000000301":9223372036854775808}'::jsonb,false)$$,'P0001','investment_cash_invalid_expected_versions','overflow cannot grant batch comparison authority');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')),'[]'::jsonb,false)$$,'P0001','investment_cash_invalid_expected_versions','array map cannot grant batch comparison authority');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301'),pg_temp.posting('59000000-0000-4000-8000-000000000301')),jsonb_build_object('59000000-0000-4000-8000-000000000301',1),false)$$,'P0001','investment_cash_invalid_batch','duplicate row IDs cannot be written twice');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301'),pg_temp.posting('59000000-0000-4000-8000-000000000302')||jsonb_build_object('user_id','59000000-0000-4000-8000-000000000002')),jsonb_build_object('59000000-0000-4000-8000-000000000301',1,'59000000-0000-4000-8000-000000000302',7),false)$$,'P0001','A cash batch must belong to one owner','mixed owner batch is rejected');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301',99),pg_temp.posting('59000000-0000-4000-8000-000000000302')),jsonb_build_object('59000000-0000-4000-8000-000000000301',1,'59000000-0000-4000-8000-000000000302',7),false)$$,'P0001','Invalid investment cash posting','foreign global ID cannot redirect an owned batch');
select is((select accounting_amount_minor from public.investment_wallet_postings where id='59000000-0000-4000-8000-000000000301'),20::bigint,'foreign-row rejection rolls back earlier owned intent');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')),jsonb_build_object('59000000-0000-4000-8000-000000000301',1),true)$$,'P0001','investment_cash_force_not_allowed','compared overload rejects true');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')),jsonb_build_object('59000000-0000-4000-8000-000000000301',1),null::boolean)$$,'P0001','investment_cash_force_not_allowed','compared overload rejects null::boolean');
update public.investment_wallet_postings set sync_version=9007199254740993 where id='59000000-0000-4000-8000-000000000301';
select lives_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301',23),pg_temp.posting('59000000-0000-4000-8000-000000000303',24)),jsonb_build_object('59000000-0000-4000-8000-000000000301',9007199254740993::bigint,'59000000-0000-4000-8000-000000000303',1),false)$$,'per-row Int64 comparisons remain exact above IEEE754');
select is((select sync_version from public.investment_wallet_postings where id='59000000-0000-4000-8000-000000000301'),9007199254740994::bigint,'large compared version advances without floating point');
select is((select sync_version from public.investment_wallet_postings where id='59000000-0000-4000-8000-000000000303'),2::bigint,'the other row uses its own compared version');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000309',1),pg_temp.posting('59000000-0000-4000-8000-000000000308',-1000)||jsonb_build_object('role_raw_value','cashConsumption')),jsonb_build_object('59000000-0000-4000-8000-000000000309',0,'59000000-0000-4000-8000-000000000308',0),false)$$,'P0001','Investment cash was already used on another device','existing cash-capacity checks still reject a later row');
select is((select count(*) from public.investment_wallet_postings where id='59000000-0000-4000-8000-000000000309'),0::bigint,'later financial failure rolls back the earlier inserted row');
select lives_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000307')),false)$$,'legacy two-argument batch remains callable');
select is((select sync_version from public.investment_wallet_postings where id='59000000-0000-4000-8000-000000000307'),1::bigint,'legacy creation retains its version contract');
select lives_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.reconciliation('59000000-0000-4000-8000-000000000401','59000000-0000-4000-8000-000000000101',-30),pg_temp.reconciliation('59000000-0000-4000-8000-000000000402','59000000-0000-4000-8000-000000000103',30)),jsonb_build_object('59000000-0000-4000-8000-000000000401',0,'59000000-0000-4000-8000-000000000402',0),false)$$,'balanced holder-to-linked reconciliation retains existing financial rules');
select is((select sum(accounting_amount_minor) from public.investment_wallet_postings where event_id='59000000-0000-4000-8000-000000000601'),0::numeric,'reconciliation cash postings balance to zero');
select is((select accounting_amount_minor from public.investment_wallet_postings where id='59000000-0000-4000-8000-000000000401'),(-30)::bigint,'holder allocation is reduced by its exact minor amount');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.reconciliation('59000000-0000-4000-8000-000000000403','59000000-0000-4000-8000-000000000101',-1,'59000000-0000-4000-8000-000000000602')),jsonb_build_object('59000000-0000-4000-8000-000000000403',0),false)$$,'P0001','A reconciliation event must contain exactly two postings','partial reconciliation cannot be published');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.reconciliation('59000000-0000-4000-8000-000000000404','59000000-0000-4000-8000-000000000101',-1,'59000000-0000-4000-8000-000000000602'),pg_temp.reconciliation('59000000-0000-4000-8000-000000000405','59000000-0000-4000-8000-000000000103',2,'59000000-0000-4000-8000-000000000602')),jsonb_build_object('59000000-0000-4000-8000-000000000404',0,'59000000-0000-4000-8000-000000000405',0),false)$$,'P0001','Reconciliation postings must balance to zero','unbalanced reconciliation retains its original guard');
select throws_ok($$select * from public.mutate_investment_cash_postings('{}'::jsonb,'{}'::jsonb,false)$$,'P0001','investment_cash_invalid_batch','object is not a batch cannot be written');
select throws_ok($$select * from public.mutate_investment_cash_postings('[]'::jsonb,'{}'::jsonb,false)$$,'P0001','investment_cash_invalid_batch','empty batch cannot be written');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')||jsonb_build_object('id',42)),'{}'::jsonb,false)$$,'P0001','investment_cash_invalid_batch','numeric row ID cannot be written');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')),null::jsonb,false)$$,'P0001','investment_cash_invalid_expected_versions','null map cannot grant comparison authority');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')),jsonb_build_object('59000000-0000-4000-8000-000000000301',9223372036854775807::bigint),false)$$,'P0001','investment_cash_invalid_expected_versions','exhausted Int64 version cannot grant comparison authority');
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000310')),jsonb_build_object('59000000-0000-4000-8000-000000000310',2),false)$$,'P0001','version_conflict','missing positive-base batch row cannot be recreated');
select is((select count(*) from public.investment_wallet_postings where id='59000000-0000-4000-8000-000000000310'),0::bigint,'missing compared identity remains absent');
select set_config('request.jwt.claim.sub','59000000-0000-4000-8000-000000000002',true);
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')),jsonb_build_object('59000000-0000-4000-8000-000000000301',9007199254740994::bigint),false)$$,'P0001','Investment edit permission is required','wrong authenticated owner cannot inspect or mutate the batch');
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select * from public.mutate_investment_cash_postings(jsonb_build_array(pg_temp.posting('59000000-0000-4000-8000-000000000301')),jsonb_build_object('59000000-0000-4000-8000-000000000301',9007199254740994::bigint),false)$$,'P0001','Authentication required','unauthenticated batch fails before financial mutation');
select set_config('request.jwt.claim.sub','59000000-0000-4000-8000-000000000001',true);
select ok(not has_function_privilege('anon','public.mutate_investment_cash_postings(jsonb,jsonb,boolean)','execute'),'anonymous callers cannot execute the new overload');
select ok(has_function_privilege('authenticated','public.mutate_investment_cash_postings(jsonb,jsonb,boolean)','execute'),'authenticated callers retain the RPC entry point');
select * from finish();
rollback;
